// ============================================================================
//  BFF портала ИСМ ПБС — срез «Производственная доска + печать».
//  Zero-dep Node-сервер: статика (public/) + JSON-API.
//
//  Конфиг (приоритет): portal/.runtime.json  >  переменные окружения  >  дефолт.
//  .runtime.json пишется со страницы «Настройки» (/admin.html); токен живёт
//  только на сервере и клиенту не возвращается.
//
//  Режимы:
//   • LIVE  — задан NC_TOKEN. Доска читает NocoDB v2 (id таблиц резолвятся через
//             meta-API, schema-map не требуется). Печать дополнительно требует
//             GOTENBERG_URL и nocodb/.state/schema-map.json (нужны рендер-скриптам).
//   • MOCK  — токена нет → демо-данные из portal/mock/fixtures.json.
// ============================================================================

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import os from 'node:os';
import crypto from 'node:crypto';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');
const PUBLIC = path.join(__dirname, 'public');
const RUNTIME_FILE = path.join(__dirname, '.runtime.json');
const MAP_PATH = path.join(ROOT, 'nocodb', '.state', 'schema-map.json');

const PORT = Number(process.env.PORT || 4173);

// --- конфиг -----------------------------------------------------------------
function loadRuntime() { try { return JSON.parse(fs.readFileSync(RUNTIME_FILE, 'utf8')); } catch { return {}; } }
let runtime = loadRuntime();
function cfg() {
  return {
    NC_URL: runtime.NC_URL || process.env.NC_URL || 'http://localhost:8080',
    NC_TOKEN: runtime.NC_TOKEN || process.env.NC_TOKEN || '',
    GOTENBERG: runtime.GOTENBERG_URL || process.env.GOTENBERG_URL || '',
    BITRIX: runtime.BITRIX_WEBHOOK || process.env.BITRIX_WEBHOOK || '',
    BITRIX_USERS: runtime.BITRIX_USERS || process.env.BITRIX_USERS || '',
    // K-156: OData 1С ПБС (зеркало номенклатуры и остатков); пароль только в runtime/env
    ONEC_URL: String(runtime.ONEC_URL || process.env.ONEC_URL || '').replace(/\/+$/, ''),
    ONEC_LOGIN: runtime.ONEC_LOGIN || process.env.ONEC_LOGIN || '',
    ONEC_PASSWORD: runtime.ONEC_PASSWORD || process.env.ONEC_PASSWORD || '',
    ONEC_WAREHOUSE: String(runtime.ONEC_WAREHOUSE ?? process.env.ONEC_WAREHOUSE ?? 'Склад производство').trim() || 'Склад производство', // K-159: склад выпуска в 1С
    SALES_DEPT: String(runtime.SALES_DEPT_ID || process.env.SALES_DEPT_ID || '81'), // отдел продаж ПБС в Bitrix → участники чата ЗП по умолчанию
    HUB_CHAT: String(runtime.BITRIX_HUB_CHAT ?? process.env.BITRIX_HUB_CHAT ?? '4175'), // хаб-чат «Запросы ПБС» → анонс новых ЗП (пусто = не слать)
    ZNZ_CHAT: String(runtime.BITRIX_ZNZ_CHAT ?? process.env.BITRIX_ZNZ_CHAT ?? '8873'), // чат «Портал ИСМ — Цеховые заявки» → анонс новых ЗнЗ (пусто = не слать)
    PORTAL_BASE: (runtime.PORTAL_BASE || process.env.PORTAL_BASE || 'http://192.168.1.10:4173').replace(/\/+$/, ''), // внешний адрес портала для ссылок в чате
    RECORDS: runtime.RECORDS_ROOT || process.env.RECORDS_ROOT || '',
    // --- запись записей ИСМ через FileStation API (DSM), см. блок fsApi* ниже ---
    // Прямая запись в ФС из контейнера НЕ видна Synology Drive: папка есть на NAS,
    // но на клиентах не появляется никогда (доказано экспериментом 18.08.2026 —
    // rename под скрытым .tmp, rename под видимым и прямой mkdir не сработали ни разу).
    // Через FileStation API те же папки и файлы уезжают на клиенты за ~15 секунд.
    // Пусто = фолбэк на прямую запись в ФС (прежнее поведение, ничего не ломается).
    // K-108: участники рабочего чата заказа по умолчанию (id Bitrix через запятую).
    // Пусто = чат создаётся только с автором вебхука; состав правится в самом чате.
    ORDER_CHAT_USERS: String(runtime.ORDER_CHAT_USERS || process.env.ORDER_CHAT_USERS || ''),
    FS_URL: (runtime.FS_URL || process.env.FS_URL || 'http://192.168.1.10:5000').replace(/\/+$/, ''),
    FS_USER: runtime.FS_USER || process.env.FS_USER || '',
    FS_PASS: runtime.FS_PASS || process.env.FS_PASS || '',
    // Путь общей папки записей в терминах FileStation (share-relative, с ведущим «/»).
    // Локально в контейнере это RECORDS (обычно /records) — сопоставление одно к одному.
    FS_RECORDS_PATH: (runtime.FS_RECORDS_PATH || process.env.FS_RECORDS_PATH || '/06-Записи-ПБС').replace(/\/+$/, ''),
    DOCS_ROOT: runtime.DOCS_ROOT || process.env.DOCS_ROOT || runtime.RECORDS_ROOT || process.env.RECORDS_ROOT || '',
    // релиз-контур РКД (ДП–Д.1.2 §8.2): записи актуальных чертежей = <RECORDS>/6.7-РТД.
    // По умолчанию выводим из RECORDS, чтобы не править compose (папка уже примонтирована в /records).
    DESIGN_ROOT: (() => {
      const explicit = runtime.DESIGN_ROOT || process.env.DESIGN_ROOT;
      if (explicit) return explicit;
      const rec = runtime.RECORDS_ROOT || process.env.RECORDS_ROOT;
      return rec ? String(rec).replace(/[\\/]+$/, '') + '/6.7-РТД' : '';
    })(),
    // Bitrix OAuth (персональный вход людей; ≠ вебхук user 11 выше).
    // K-49: приоритет у ключей нового OAuth-приложения (BITRIX_OAUTH_*), затем — старые BITRIX_*.
    BX_CLIENT_ID: runtime.BITRIX_OAUTH_CLIENT_ID || runtime.BITRIX_CLIENT_ID || process.env.BITRIX_OAUTH_CLIENT_ID || process.env.BITRIX_CLIENT_ID || '',
    BX_CLIENT_SECRET: runtime.BITRIX_OAUTH_CLIENT_SECRET || runtime.BITRIX_CLIENT_SECRET || process.env.BITRIX_OAUTH_CLIENT_SECRET || process.env.BITRIX_CLIENT_SECRET || '',
    // Домен портала Bitrix24: из BITRIX_PORTAL_URL (полный URL) → нормализуем до хоста; фолбэк — BITRIX_DOMAIN, дефолт endv.
    BX_DOMAIN: (runtime.BITRIX_PORTAL_URL || runtime.BITRIX_DOMAIN || process.env.BITRIX_PORTAL_URL || process.env.BITRIX_DOMAIN || 'endv.bitrix24.ru').replace(/^https?:\/\//, '').replace(/\/+$/, ''),
    // Явный redirect_uri OAuth-приложения (если задан — используется как есть; иначе PORTAL_BASE + /auth/callback).
    BX_REDIRECT: runtime.BITRIX_OAUTH_REDIRECT || process.env.BITRIX_OAUTH_REDIRECT || '',
    // Локальный админ-обход (на случай сбоя SSO): GET /auth/admin?token=… → сессия Администратора.
    ADMIN_BYPASS_TOKEN: runtime.ADMIN_BYPASS_TOKEN || process.env.ADMIN_BYPASS_TOKEN || '',
    // --- интеграция с payment-portal (K-83, «Отправить на оплату») ---
    // База ingest-API шлюза (дефолт из контракта docs/INTEGRATION_ISM.md).
    PAYMENT_API_BASE: (runtime.PAYMENT_API_BASE || process.env.PAYMENT_API_BASE || 'https://d5dhb8rdt4vqg4mju8a3.avjje9e3.apigw.yandexcloud.net').replace(/\/+$/, ''),
    // Сервисный ключ X-API-Key (формат pin_…). НЕ хардкод: кладётся в runtime.json оператором при деплое
    // (совместимо и с ключом INGEST_API_KEY). Для локального теста — env PAYMENT_INGEST_KEY. Пусто → эндпойнты 501.
    PAYMENT_INGEST_KEY: runtime.PAYMENT_INGEST_KEY || runtime.INGEST_API_KEY || process.env.PAYMENT_INGEST_KEY || process.env.INGEST_API_KEY || '',
    // Наш id юр.лица в payment-portal (ПБС = 4, см. §1 контракта).
    PAYMENT_LEGAL_ENTITY_ID: numOr(runtime.PAYMENT_LEGAL_ENTITY_ID ?? process.env.PAYMENT_LEGAL_ENTITY_ID, 4),
    // K-83: ключ Yandex Cloud OCR (автозаполнение полей счёта по скану). НИКОГДА не логировать значение.
    YC_OCR: String(runtime.YC_OCR_API_KEY || process.env.YC_OCR_API_KEY || ''),
    DEPT_ROLE: runtime.DEPT_ROLE || null,         // карта департамент Bitrix → роль (правится в «Настройках»)
    ROLE_OVERRIDES: runtime.ROLE_OVERRIDES || null, // карта user-id Bitrix → роли[]
    // --- параметры продаж/КП (K-05, ДП–З.1 §5.3) — «магические числа» вынесены в «Настройки», не хардкод ---
    KP_SIGN_THRESHOLD: numOr(runtime.KP_SIGN_THRESHOLD ?? process.env.KP_SIGN_THRESHOLD, 1000000), // §5.3.5 порог подписи ДпП↔ГД, ₽ без НДС (заглушка до приказа)
    KP_VAT_RATE: numOr(runtime.KP_VAT_RATE ?? process.env.KP_VAT_RATE, 22),                        // ставка НДС, % (дефолт 22; правится в «Настройках»/runtime.json/env KP_VAT_RATE без деплоя)
    KP_PROFIT_PCT: numOr(runtime.KP_PROFIT_PCT ?? process.env.KP_PROFIT_PCT, 15),                  // §5.3.4 плановая прибыль по умолчанию, % (утверждает ДпП)
    KP_SLA_PREP_DAYS: numOr(runtime.KP_SLA_PREP_DAYS ?? process.env.KP_SLA_PREP_DAYS, 5),          // §5.3.6 срок подготовки КП, раб.дн
    KP_SLA_FOLLOWUP_DAYS: numOr(runtime.KP_SLA_FOLLOWUP_DAYS ?? process.env.KP_SLA_FOLLOWUP_DAYS, 10), // §5.3.8 повтор при отсутствии ответа, раб.дн
  };
}
// парсер числа из runtime/env с фолбэком (пустое/NaN → дефолт)
function numOr(v, def) { const n = Number(v); return Number.isFinite(n) && v !== '' && v != null ? n : def; }
const hasMap = () => fs.existsSync(MAP_PATH);
const isLive = () => !!cfg().NC_TOKEN;

