let _tm = null, _tmKey = '';
async function tableMap() {
  const c = cfg();
  if (!c.NC_TOKEN) throw new Error('Не задан токен NocoDB (страница «Настройки»).');
  const key = c.NC_URL + '|' + c.NC_TOKEN;
  if (_tm && _tmKey === key) return _tm;
  const h = { 'xc-token': c.NC_TOKEN };
  const pr = await fetch(`${c.NC_URL}/api/v1/db/meta/projects`, { headers: h });
  if (!pr.ok) throw new Error(`NocoDB meta ${pr.status}: ${await pr.text()}`);
  const bases = (await pr.json()).list || [];
  const base = bases.find((b) => b.title === 'Производство ПБС') || bases[0];
  if (!base) throw new Error('База «Производство ПБС» не найдена.');
  const tr = await fetch(`${c.NC_URL}/api/v1/db/meta/projects/${base.id}/tables?includeM2M=false`, { headers: h });
  if (!tr.ok) throw new Error(`NocoDB tables ${tr.status}`);
  const tables = (tr.json ? (await tr.json()).list : []) || [];
  _tm = { base: base.title, byTitle: Object.fromEntries(tables.map((t) => [t.title, t.id])) };
  _tmKey = key;
  return _tm;
}
async function tid(key) {
  const m = await tableMap();
  const id = m.byTitle[KEY2TITLE[key]];
  if (!id) throw new Error(`Таблица «${KEY2TITLE[key]}» не найдена в базе.`);
  return id;
}
async function ncList(key) {
  const c = cfg();
  const url = `${c.NC_URL}/api/v2/tables/${await tid(key)}/records?limit=1000`;
  const res = await fetch(url, { headers: { 'xc-token': c.NC_TOKEN } });
  if (!res.ok) throw new Error(`NocoDB ${res.status}: ${await res.text()}`);
  return (await res.json()).list || [];
}
// K-156: чтение большой таблицы целиком (ncList режет на 1000) — постранично через offset
async function ncListAll(key) {
  const c = cfg(); const id = await tid(key); const out = [];
  for (let off = 0; off < 200000; off += 1000) {
    const res = await fetch(`${c.NC_URL}/api/v2/tables/${id}/records?limit=1000&offset=${off}`, { headers: { 'xc-token': c.NC_TOKEN } });
    if (!res.ok) throw new Error(`NocoDB ${res.status}: ${await res.text()}`);
    const j = await res.json(); const list = j.list || []; out.push(...list);
    if (list.length < 1000 || (j.pageInfo && j.pageInfo.isLastPage)) break;
  }
  return out;
}

// --- реестр документов ИСМ (отдельная база «ИСМ ПБС», резолв по meta) --------
let _docsTid = null, _docsKey = '';
async function ismDocsTid() {
  const c = cfg();
  if (!c.NC_TOKEN) throw new Error('Не задан токен NocoDB.');
  const key = c.NC_URL + '|' + c.NC_TOKEN;
  if (_docsTid && _docsKey === key) return _docsTid;
  const h = { 'xc-token': c.NC_TOKEN };
  const pr = await fetch(`${c.NC_URL}/api/v1/db/meta/projects`, { headers: h });
  if (!pr.ok) throw new Error(`NocoDB meta ${pr.status}`);
  const base = ((await pr.json()).list || []).find((b) => b.title === 'ИСМ ПБС');
  if (!base) throw new Error('База «ИСМ ПБС» не найдена.');
  const tr = await fetch(`${c.NC_URL}/api/v1/db/meta/projects/${base.id}/tables?includeM2M=false`, { headers: h });
  const t = ((await tr.json()).list || []).find((x) => x.title === 'Документы ИСМ');
  if (!t) throw new Error('Таблица «Документы ИСМ» не найдена.');
  _docsTid = t.id; _docsKey = key;
  return _docsTid;
}
// поля-кандидаты, в которых может лежать путь к файлу документа на NAS
const DOCS_FILE_FIELDS = ['Файл', 'Файл (NAS)', 'Файл документа', 'PDF на NAS', 'Путь', 'Путь на NAS'];
async function buildDocs() {
  const c = cfg();
  // без fields= — берём все колонки таблицы (схема «ИСМ ПБС» может отличаться/расширяться)
  const url = `${c.NC_URL}/api/v2/tables/${await ismDocsTid()}/records?limit=1000`;
  const res = await fetch(url, { headers: { 'xc-token': c.NC_TOKEN } });
  if (!res.ok) throw new Error(`NocoDB ${res.status}: ${await res.text()}`);
  return ((await res.json()).list || []).filter((r) => r['Код']).map((r) => {
    let file = '';
    for (const f of DOCS_FILE_FIELDS) { if (r[f]) { file = String(r[f]); break; } }
    // «UNC мастера» — путь файла под управлением портала: «draft:<имя>» (черновик) или rel под DOCS_ROOT (опубликован)
    const unc = String(r['UNC мастера'] || '');
    let fileRel = '', draft = '';
    if (unc.startsWith('draft:')) draft = unc.slice(6);
    else if (unc) {
      // «UNC мастера» бывает Windows-UNC «\\host\share\03-…\file» или уже rel «03-…/file» → приводим к rel под DOCS_ROOT
      let rel = unc.replace(/\\/g, '/');
      const m = rel.match(/(0[1-7]-[^/]*?-ПБС\/.*)$/);
      rel = m ? m[1] : rel.replace(/^\/+[^/]+\/[^/]+\//, '');
      const root = cfg().DOCS_ROOT;
      // если файл по указанному пути есть — используем; иначе фолбэк на поиск по коду
      fileRel = (root && fs.existsSync(path.join(root, rel))) ? rel : (docsResolveFile(r['Код']) || '');
    }
    else fileRel = file || docsResolveFile(r['Код']) || ''; // фолбэк: поиск по коду на NAS
    const fileExt = ((draft || fileRel).split('.').pop() || '').toLowerCase();
    return {
      id: r.Id, code: r['Код'] || '', name: r['Название'] || '', type: r['Тип'] || '', section: r['Раздел'] || '',
      ver: r['Версия'] || '', status: r['Статус'] || '', format: r['Формат'] || '',
      approvedDate: r['Дата утверждения'] || '', approvedBy: r['Утверждён'] || '', file, fileRel, fileExt, draft, unc,
    };
  }).sort((a, b) => String(a.code).localeCompare(String(b.code), 'ru'));
}
// --- CRUD над таблицей «Документы ИСМ» (база «ИСМ ПБС») ----------------------
// whitelist полей, которые портал вправе писать (только существующие в таблице)
const DOC_WRITE_FIELDS = ['Код', 'Название', 'Тип', 'Раздел', 'Версия', 'Статус', 'Формат', 'Дата утверждения', 'Утверждён'];
function buildDocPatch(body) {
  const patch = {};
  for (const k of DOC_WRITE_FIELDS) if (body[k] != null && body[k] !== '') patch[k] = String(body[k]);
  return patch;
}
async function ncDocsWrite(method, rows) {
  const c = cfg();
  if (!c.NC_TOKEN) throw new Error('Не задан токен NocoDB.');
  const url = `${c.NC_URL}/api/v2/tables/${await ismDocsTid()}/records`;
  const res = await fetch(url, {
    method, headers: { 'xc-token': c.NC_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify(rows),
  });
  if (!res.ok) throw new Error(`NocoDB ${res.status}: ${await res.text()}`);
  return res.json().catch(() => null);
}
// --- поиск файла документа на NAS («Сервер ПБС») по коду ---------------------
// нормализация кода/имени: убираем регистр, пробелы, разные тире → латиница не трогаем
const docNorm = (s) => String(s || '').toLowerCase().replace(/[\s_]+/g, '').replace(/[–—−]/g, '-');
let _docFileIdx = null, _docFileIdxKey = '';
// строит индекс {нормкод → relPath} обходом DOCS_ROOT (ограничение глубины/кол-ва)
function docsFileIndex() {
  const root = cfg().DOCS_ROOT;
  if (!root) return {};
  if (_docFileIdx && _docFileIdxKey === root) return _docFileIdx;
  const idx = {}; let seen = 0;
  const exts = /\.(pdf|docx?|xlsx?|pptx?|odt|ods|odp|rtf)$/i;
  const SKIP_DIR = /^(@eaDir|#recycle|#snapshot|\.)/i; // служебные папки Synology
  const walk = (dir, depth) => {
    if (depth > 6 || seen > 20000) return;
    let ents; try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of ents) {
      if (SKIP_DIR.test(e.name)) continue;
      const full = path.join(dir, e.name);
      if (e.isDirectory()) { walk(full, depth + 1); continue; }
      seen++;
      if (!exts.test(e.name)) continue;
      const rel = path.relative(root, full).split(path.sep).join('/');
      const nn = docNorm(e.name);
      // привязываем к первому встреченному файлу для каждого кода-подстроки делаем при запросе
      idx[rel] = nn; // храним rel→норм.имя, матч кода — при запросе
    }
  };
  try { walk(root, 0); } catch {}
  _docFileIdx = idx; _docFileIdxKey = root;
  return idx;
}
// находит rel-путь файла по коду. Приоритет: точное совпадение с версией («…дп-д.1-1.1…»),
// иначе — по базовому коду без версии («…ф.2-л.1…», т.к. в части имён форм версии нет).
// При прочих равных берём файл с более коротким путём (активная папка, не 07-Архив).
function docsResolveFile(code) {
  const full = docNorm(code);            // напр. «дп-д.1-1.1» (с версией, если она в коде)
  const bare = full.replace(/-\d+\.\d+$/, ''); // напр. «дп-д.1»
  if (!bare) return null;
  const hasVer = full.length > bare.length;
  const idx = docsFileIndex();
  let exact = null, loose = null;
  for (const rel in idx) {
    const nn = idx[rel];
    if (hasVer && nn.includes(full) && (!exact || rel.length < exact.length)) exact = rel;
    if (nn.includes(bare) && (!loose || rel.length < loose.length)) loose = rel;
  }
  return exact || loose;
}
// --- загрузка/публикация файлов документов -----------------------------------
const DRAFTS_DIR = path.join(__dirname, 'docs-drafts');           // черновики (под rw-маунтом /app)
const LEVEL_FOLDER = { 1: '01-Руководство-и-политика-ПБС', 2: '02-Процедуры-ПБС', 3: '04-Рабочие-инструкции-ПБС', 4: '03-Формы-и-приложения-ПБС' };
// каноничное имя файла на NAS: «Код Название.ext» (как уже принято в папках)
function canonDocName(code, name, ext) {
  const clean = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, '_').replace(/\s+/g, ' ').trim();
  const base = (clean(code) + ' ' + clean(name)).trim() || clean(code) || 'документ';
  const e = String(ext || '').replace(/[^a-z0-9]/gi, '').toLowerCase();
  return e ? `${base}.${e}` : base;
}
// --- журнал изменений документов (Лист регистрации изменений Ф.3–Л.1) --------
// Персистентное файловое хранилище (без миграции NocoDB): один JSON под rw-маунтом /app.
// Ключ — код документа без версии-хвоста (журнал сквозной по всем версиям документа).
const DOCS_CHANGES_FILE = path.join(__dirname, 'docs-changes.json');
const changeKey = (code) => docNorm(String(code || '').replace(/[–—−-]\d+\.\d+$/, ''));
function readChangeStore() {
  try { return JSON.parse(fs.readFileSync(DOCS_CHANGES_FILE, 'utf8')) || {}; } catch { return {}; }
}
function writeChangeStore(obj) {
  try { fs.writeFileSync(DOCS_CHANGES_FILE, JSON.stringify(obj, null, 2)); return true; } catch { return false; }
}
function docChangeLog(code) { return readChangeStore()[changeKey(code)] || []; }
function appendDocChange(code, entry) {
  const store = readChangeStore(), k = changeKey(code), arr = store[k] || [];
  const no = arr.length ? Math.max(...arr.map((r) => +r.no || 0)) + 1 : 1;
  const row = {
    no, date: String(entry.date || '').slice(0, 10),
    verFrom: String(entry.verFrom || ''), verTo: String(entry.verTo || ''),
    desc: String(entry.desc || ''), approvedDoc: String(entry.approvedDoc || ''),
    approver: String(entry.approver || ''), ts: new Date().toISOString(),
  };
  arr.push(row); store[k] = arr; writeChangeStore(store);
  return row;
}
// фирменный логотип ПБС как самодостаточный data-URI (тот же ассет, что и во фронте: public/assets/PBS_LOGO_2026.png).
// Встраиваем base64, чтобы бланк оставался самодостаточным HTML при сохранении/печати в PDF (в т.ч. через изолированный Gotenberg). Читаем один раз, кэшируем.
let _pbsLogoDataUri;
function pbsLogoDataUri() {
  if (_pbsLogoDataUri !== undefined) return _pbsLogoDataUri;
  try { _pbsLogoDataUri = 'data:image/png;base64,' + fs.readFileSync(path.join(__dirname, 'public', 'assets', 'PBS_LOGO_2026.png')).toString('base64'); }
  catch { _pbsLogoDataUri = ''; }
  return _pbsLogoDataUri;
}
// K-162: монохромный вариант логотипа для бланков, которые печатают на ч/б принтере (решение владельца 05.09) — public/assets/PBS_LOGO_2026_mono.png
let _pbsLogoMonoDataUri;
function pbsLogoMonoDataUri() {
  if (_pbsLogoMonoDataUri !== undefined) return _pbsLogoMonoDataUri;
  try { _pbsLogoMonoDataUri = 'data:image/png;base64,' + fs.readFileSync(path.join(__dirname, 'public', 'assets', 'PBS_LOGO_2026_mono.png')).toString('base64'); }
  catch { _pbsLogoMonoDataUri = pbsLogoDataUri(); }
  return _pbsLogoMonoDataUri;
}
// бланк «Лист регистрации изменений к документам ИСМ» (Ф.3–Л.1) — 1:1 к утверждённому PDF,
// самодостаточный HTML для печати/сохранения в PDF браузером (тот же фирменный колонтитул, что и у др. бланков).
