function casingRead() { try { const j = JSON.parse(fs.readFileSync(CASING_FILE, 'utf8')); if (j && Array.isArray(j.sizes) && j.sizes.length) return j; } catch {} return CASING_SEED; }
// плоские строки размеров: NocoDB casing_sizes (истина) → фолбэк файл/сид.
async function casingRowsRaw() {
  try {
    const rows = await ncListSoft('casing_sizes');
    if (rows && rows.length) {
      const mapped = rows.map((r) => ({
        odCanon: Number(r['Ø канонический, мм']), odExact: Number(r['Ø точный, мм']),
        odIn: String(r['Ø, дюйм'] || '').trim(), wall: Number(r['Толщина стенки, мм']),
      })).filter((x) => Number.isFinite(x.odCanon) && Number.isFinite(x.wall));
      if (mapped.length) return mapped;
    }
  } catch {}
  return (casingRead().sizes || []).map((s) => ({ odCanon: Number(s.odCanon), odExact: Number(s.odExact), odIn: String(s.odIn || ''), wall: Number(s.wall) }));
}
// для клиента: группировка по каноническому Ø (уникальные Ø + union толщин).
//  [{ odCanon, odIn, odExacts[], walls[] }] отсортировано по Ø. Конструктор ПЧ:
//  Ø-выпадашка = odCanon, стенка = фильтр walls выбранного Ø. Резьба не участвует.
async function casingSizesPayload() {
  const raw = await casingRowsRaw();
  const byCanon = new Map();
  for (const r of raw) {
    const k = r.odCanon.toFixed(1);
    let g = byCanon.get(k);
    if (!g) { g = { odCanon: r.odCanon, odIn: r.odIn, exacts: new Set(), walls: new Set() }; byCanon.set(k, g); }
    if (!g.odIn && r.odIn) g.odIn = r.odIn;
    if (Number.isFinite(r.odExact)) g.exacts.add(r.odExact);
    g.walls.add(r.wall);
  }
  return [...byCanon.values()].map((g) => ({
    odCanon: g.odCanon, odIn: g.odIn,
    odExacts: [...g.exacts].sort((a, b) => a - b),
    walls: [...g.walls].sort((a, b) => a - b),
  })).sort((a, b) => a.odCanon - b.odCanon);
}
// материалы уплотнения ПЧ (базовый список; РИ.1 Прил.Б — код идёт в обозначение).
// Расширяется добавлением строк (при обновлении РИ заказчиком).
// K-126: исполнения по УТВЕРЖДЁННОМУ перечню наименований и артикулов ПЧ (ТПП).
// Было одно и с чужим названием — конструктор не мог собрать 120 позиций из 180.
const PCH_MATERIALS = [
  { code: '00', name: 'NBR75 (базовый)' },
  { code: '01', name: 'NBR85 (NB85901)' },
  { code: '02', name: 'HNBR80 (HN80120)' },
];
// реестр проектов ПЧ (Ф.3–П.1) для селектора «№ проекта»: децим.№ вида ПЧnnnn.
async function pchProjectsPayload() {
  try {
    const rows = await ncListSoft('design_projects');
    return rows.map((r) => ({ decNo: String(r['Децимальный номер'] || '').trim(), name: String(r['Наименование изделия'] || '').trim() }))
      .filter((x) => /^ПЧ\d{4}$/.test(x.decNo))
      .sort((a, b) => a.decNo.localeCompare(b.decNo, 'ru'));
  } catch { return []; }
}
// K-127: конструкторы обозначений теперь есть не только у ПЧ (ЦТ, дальше ПР и УВ),
//  поэтому нужен ОБЩИЙ реестр проектов: код подгруппы + 4 цифры. Клиент фильтрует по префиксу.
async function designProjectsPayload() {
  try {
    const rows = await ncListSoft('design_projects');
    return rows.map((r) => ({ decNo: String(r['Децимальный номер'] || '').trim(), name: String(r['Наименование изделия'] || '').trim() }))
      .filter((x) => /^[А-ЯA-Z]{2,4}\d{4}$/.test(x.decNo))
      .sort((a, b) => a.decNo.localeCompare(b.decNo, 'ru'));
  } catch { return []; }
}
function drawMassSet(designation, mass) {
  const key = drawKey(designation); if (!key) return;
  const m = drawMassRead();
  m[key] = { designation: String(designation).trim(), mass: (mass === '' || mass == null) ? '' : Number(mass), ts: new Date().toISOString() };
  drawMassWrite(m);
}
// нормализация грузового места и его позиций (белый список полей — без мусора из клиента)
function logiNormPlace(pl) {
  const items = Array.isArray(pl && pl.items) ? pl.items : [];
  return {
    id: (pl && pl.id) || ('pl' + Math.random().toString(36).slice(2, 8)),
    kind: String((pl && pl.kind) || ''), no: String((pl && pl.no) || ''),
    dims: String((pl && pl.dims) || ''), note: String((pl && pl.note) || ''),
    items: items.map((it) => ({
      posId: (it && it.posId != null) ? it.posId : null,
      numPos: String((it && it.numPos) || ''), name: String((it && it.name) || ''),
      drawing: String((it && it.drawing) || ''), unit: String((it && it.unit) || ''),
      qty: (it && it.qty !== '' && it.qty != null) ? Number(it.qty) : '',
      massTheor: (it && it.massTheor !== '' && it.massTheor != null) ? Number(it.massTheor) : '',
      massFact: (it && it.massFact !== '' && it.massFact != null) ? Number(it.massFact) : '',
    })),
  };
}
// нормализация упаковочного листа (1 лист = 1 производственный заказ, ТЗ §2/§3)
function logiNormPackingList(x) {
  const places = Array.isArray(x && x.places) ? x.places : [];
  return {
    id: (x && x.id) || ('upl' + Math.random().toString(36).slice(2, 8)),
    plNo: String((x && x.plNo) || ''), orderPz: String((x && x.orderPz) || ''),
    orderId: (x && x.orderId != null) ? x.orderId : null, note: String((x && x.note) || ''),
    places: places.map(logiNormPlace),
  };
}
// нормализация заявки на перевозку (состав по ТЗ §6)
function logiNormShipment(x, prev) {
  const pls = Array.isArray(x && x.packingLists) ? x.packingLists : [];
  const S = (k) => String((x && x[k]) || '');
  return {
    id: (prev && prev.id) || (x && x.id) || null,
    num: (prev && prev.num) || S('num'),
    type: LOGI_TYPES.includes(S('type')) ? S('type') : LOGI_TYPES[0],
    status: LOGI_STATUSES.includes(S('status')) ? S('status') : LOGI_STATUSES[0],
    shipper: S('shipper'), shipperAddr: S('shipperAddr'), shipperContact: S('shipperContact'),
    consignee: S('consignee'), consigneeAddr: S('consigneeAddr'), consigneeContact: S('consigneeContact'),
    carrier: S('carrier'), transport: S('transport'), incoterms: S('incoterms'),
    cost: S('cost'), currency: S('currency') || '₽',
    planShip: S('planShip'), factShip: S('factShip'), planDeliver: S('planDeliver'), factDeliver: S('factDeliver'),
    saleZkz: S('saleZkz'), saleContract: S('saleContract'), purchaseReq: S('purchaseReq'),
    docs: S('docs'), note: S('note'),
    packingLists: pls.map(logiNormPackingList),
    ts: (prev && prev.ts) || new Date().toISOString(),
    updatedTs: new Date().toISOString(),
  };
}
function logiNextNum(store) {
  const year = new Date().getFullYear();
  store.seq = (store.seq || 0) + 1;
  return `ЗПер-${year}-${String(store.seq).padStart(3, '0')}`;
}
// печатный упаковочный лист (packing list) — фирменный стиль ИСМ (TNR/синий #1F4E79,
// колонтитул «Страница N из M»). Код формы — placeholder (присваивает ИСМ по Ф.2–Л.1).
