      return `<tr>${i === 0 ? `<td class="c" rowspan="${its.length}"><b>${hesc(pk.no || '—')}</b><br><span style="font-size:8.5px;color:#555">${hesc(pk.kind || '')}</span>${pk.dims ? `<br><span style="font-size:8px;color:#777">${hesc(pk.dims)}</span>` : ''}</td>` : ''}`
