    await retroEnsureApprovalCols();
    try { await ncEnsureColumn('retro_outputs', 'Документ 1С (заменён)', 'LongText'); } catch (e) { console.warn('[retro] колонка «Документ 1С (заменён)»:', e.message); }
    replacedNo = a['Документ 1С (№)'] || '';
