    const sent = await retroChatNotify(`📄 ${act.no} «${act.name}» — ${act.qty} ${act.unit}, ${act.whereTo || ''}\n${line1c}\nАкт в портале: ${cfg().PORTAL_BASE}/#retro/${act.id}`);
