  for (const ch of t) { const c = ch.charCodeAt(0); vals.push(c >= 32 && c <= 126 ? c - 32 : 0); }
  let sum = vals[0]; for (let i = 1; i < vals.length; i++) sum += vals[i] * i; vals.push(sum % 103); vals.push(106);
