      const body = await readBody(req);
      const key = String(body.key || '');
      const ids = Array.isArray(body.ids) ? body.ids.map((x) => Number(x)).filter((n) => Number.isFinite(n)) : [];
      if (!DELETABLE.has(key)) return sendJson(res, 400, { error: `Удаление из таблицы «${key}» не разрешено.` });
      if (!ids.length) return sendJson(res, 400, { error: 'Не переданы Id записей.' });
