        if (!inc) return sendJson(res, 404, { error: 'Строка входного контроля не найдена.' });
        const scans = Array.isArray(inc['Сканы']) ? inc['Сканы'] : [];
        const att = scans[n];
        if (!att) return sendJson(res, 404, { error: 'У этой строки нет прикреплённого скана.' });
        const buf = await downloadNcAttachment(att);
        const fname = att.title || att.fileName || att.name || 'scan.pdf';
